import base64
import struct

data = ""
decoded = base64.b64decode(data)
# Godot 4 tilemap format is usually 3 ints per cell (x, y, source_id, atlas_x, atlas_y, alternative_tile) packed into bits
# Let's just print the raw 16-bit or 32-bit ints
ints = struct.unpack(f'<{len(decoded)//4}i', decoded)
cells = []
for i in range(0, len(ints), 3):
    if i+1 < len(ints):
        cells.append((ints[i], ints[i+1]))
print(cells)
